def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/archeology/input/climateMeasurements.xlsx'
    xl = pd.ExcelFile(path)
    return pd.DataFrame({'sheet_name': xl.sheet_names})

def process(climateMeasurements):
    import pandas as pd
    df = climateMeasurements.copy()
    # find rows that contain keywords
    keywords = ['dust', 'wet', 'dry', 'index', 'calcium', 'ca', 'ppm']
    out_rows = []
    for i in range(min(len(df), 200)):
        row = df.iloc[i].astype(str).str.lower()
        text = ' | '.join(row.tolist())
        if any(k in text for k in keywords):
            out_rows.append({'row_index': i, 'row_text': text[:500]})
    return pd.DataFrame(out_rows)
